const Unit: number = 3
const Zero: number = 0
const Ticks: number[] = [1]
module Box(Seed: number) {
const Selected: point = if (@Seed > 0) { coordinate(x: @Seed + 3, y: 17) } else { coordinate(x: @Seed / 0, y: 29) }
export point Mark = from(source: @Selected)
}
instance Dormant(enabled: false) = Box(Seed: 0)
const Forwarded: point = @Dormant::Mark
point Blocked = from(source: @Forwarded)
for Tick in @Ticks {
instance Live = Box(Seed: @Tick)
point Observed = from(source: @Live::Mark)
}
const Independent: number = @Unit / @Zero
const Surviving: number = @Unit + 9

